window.products.push({"id":381659,"name":"One Tree Hill TV Cast Autographed Signed Reprint 8.5x11 UNFRAMED Script - Sophia Bush, Brooke Davis, Bethany Joy Lenz, Haley James Scott, James Laffer","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/61KVVzFjKbL._AC_SL1080_.jpg","description":"Featuring complete One Tree Hill episode script with a cover with cast autographs. Choose between a framed option or just the script. This item would make a great addition to your living room bedroom bar sports room or office and makes a great gift for fans throughout the year.  This memorabilia item bears reprinted signatures. The signature is part of the manufacturing process and therefore it is not an originally autographed item.  Search our Amazon storefront for other prints featuring other items for TV Music Movie Sports and Celebs!","images":["https://m.media-amazon.com/images/I/61KVVzFjKbL._AC_SL1080_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Autograph101","source_asin":"B08L1J71GD","category_path":"Home & Kitchen"},"sku":"BM-381659","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B08L1J71GD","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B08L1J71GD","price_pending":true,"merchant_ready":false});
